import sys
import json
import random
import os
import ast

def parse_recipe(file_path):
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = [line.strip() for line in f.readlines() if line.strip()]

    recipe = {}
    for line in lines:
        if not line.startswith('#'):
            try:
                name, expr = line.split('=', 1)
                name = name.strip()
                expr = expr.strip()
                if not name or not expr:
                    raise ValueError("Empty name or expression")
                if not name.startswith(ast.literal_eval(name)[0]):
                    raise ValueError("Invalid name format")
                if not ast.literal_eval(name):
                    raise ValueError("Invalid name format")
                # Validate expression
                tree = ast.parse(expr, mode='eval')
                if not all(isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load) for n in ast.walk(tree)):
                    raise ValueError("Invalid expression")
                # Evaluate expression
                local_vars = {k: v for k, v in recipe.items()}
                try:
                    value = eval(expr, {'__builtins__': None}, local_vars)
                except:
                    raise ValueError("Expression evaluation failed")
                recipe[name] = value
            except ValueError as e:
                print(f"Error parsing recipe: {e}", file=sys.stderr)
                sys.exit(1)
    return recipe

def generate_run_id():
    return ''.join(f'{random.getrandbits(16):04x}' for _ in range(4))

