import sys
import json
import random
import re
from typing import Dict, Any, List

def parse_recipe_line(line: str) -> tuple[str, Any]:
    line = line.strip()
    if not line:
        return None, None
    match = re.match(r'([A-Za-z_][A-Za-z0-9_]*)\s*=\s*([^=]*)', line)
    if not match:
        return None, None
    name, expr = match.groups()
    try:
        value = eval(expr, {'__builtins__': None}, {})
    except:
        return None, None
    return name, value

def validate_json_compatible(value: Any) -> bool:
    if value is None:
        return True
    if isinstance(value, bool):
        return True
    if isinstance(value, (int, float)):
        return True
    if isinstance(value, str):
        return True
    if isinstance(value, list):
        return all(validate_json_compatible(v) for v in value)
    if isinstance(value, dict):
        return all(isinstance(k, str) and validate_json_compatible(v) for k, v in value.items())
    return False

def process_recipe(recipe_path: str) -> Dict[str, Any]:
    with open(recipe_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    names = []
    bindings = {}

    for line in lines:
        name, value = parse_recipe_line(line)
        if name is None:
            print("recipe error", file=sys.stderr)
            sys.exit(1)
        if value is None:
            print("recipe error", file=sys.stderr)
            sys.exit(1)
        if not validate_json_compatible(value):
            print("recipe error", file=sys.stderr)
            sys.exit(1)
        if name in bindings:
            print("recipe error", file=sys.stderr)
            sys.exit(1)
        bindings[name] = value
        names.append(name)

    return {'run_id': ''.join(f'{random.getrandbits(8):02x}' for _ in range(16)), 'results': dict(zip(names, bindings))}

def main():
    recipe_path = sys.stdin.readline().strip()
    output_path = sys.stdin.readline().strip()

    try:
        result = process_recipe(recipe_path)
        with open(output_path, 'w', encoding='utf-8') as f:
            json.dump(result, f, ensure_ascii=False, indent=None)
    except Exception:
        print("recipe error", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

import sys
import json
import random
import os
import ast

def read_input():
    lines = sys.stdin.readlines()
    recipe_path = lines[0].strip()
    output_path = lines[1].strip()
    return recipe_path, output_path

def parse_recipe(recipe_path):
    with open(recipe_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()
    variables = {}
    for line in lines:
        stripped_line = line.strip()
        if not stripped_line:
            continue
        try:
            # Parse the line into name and expression
            name, expr = ast.literal_eval(f"({stripped_line})")
            # Clean up the expression to remove any surrounding whitespace
            expr_str = ast.unparse(ast.parse(f"({stripped_line})", mode='eval')).strip()
            expr = ast.literal_eval(expr_str)
        except (ValueError, SyntaxError):
            print("recipe error", file=sys.stderr)
            sys.exit(1)

        # Evaluate the expression with existing variables
        try:
            # Create a local namespace with existing variables
            namespace = {}
            for var, val in variables.items():
                namespace[var] = val
            # Evaluate the expression
            result = eval(expr, {'__builtins__': None}, namespace)
        except Exception:
            print("recipe error", file=sys.stderr)
            sys.exit(1)

        # Check if the result is JSON-compatible
        def is_json_compatible(obj):
            if obj is None:
                return True
            if isinstance(obj, (bool, int, float)):
                return True
            if isinstance(obj, str):
                return True
            if isinstance(obj, list):
                return all(is_json_compatible(item) for item in obj)
            if isinstance(obj, dict):
                return all(is_json_compatible(v) for v in obj.values())
            return False

        if not is_json_compatible(result):
            print("recipe error", file=sys.stderr)
            sys.exit(1)

        variables[name] = result
    return variables

def generate_run_id():
    return ''.join([f'{random.getrandbits(8):02x}' for _ in range(16)])

def write_output(output_path, variables, run_id):
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump({
            'run_id': run_id,
            'results': variables
        }, f, ensure_ascii=False, indent=2)

def main():
    recipe_path, output_path = read_input()
    variables = parse_recipe(recipe_path)
    run_id = generate_run_id()
    write_output(output_path, variables, run_id)

if __name__ == "__main__":
    main()

import sys
import json
import random
import os
import ast

def read_recipe_file(path):
    with open(path, 'r', encoding='utf-8') as f:
        return [line.strip() for line in f.readlines()]

def parse_expression(expr):
    try:
        return ast.literal_eval(expr)
    except (ValueError, SyntaxError):
        return None

def evaluate_expression(expr, globals_dict):
    try:
        return eval(expr, globals_dict, {})
    except Exception:
        return None

def process_recipe(recipe_lines):
    globals_dict = {}
    for line in recipe_lines:
        if '=' not in line:
            continue
        name_part, expr_part = line.split('=', 1)
        name = name_part.strip()
        expr = expr_part.strip()

        if not name.isidentifier():
            continue

        if expr:
            parsed = parse_expression(expr)
            if parsed is not None:
                globals_dict[name] = parsed
            else:
                if evaluate_expression(expr, globals_dict) is None:
                    sys.stderr.write('error\n')
                    sys.exit(1)
        else:
            globals_dict[name] = None

    return globals_dict

def generate_run_id():
    return ''.join([f'{random.getrandbits(8):02x}' for _ in range(16)])

def main():
    recipe_path = sys.stdin.readline().rstrip()
    output_path = sys.stdin.readline().rstrip()

    recipe_lines = read_recipe_file(recipe_path)
    globals_dict = process_recipe(recipe_lines)

    run_id = generate_run_id()
    results = {name: globals_dict[name] for name in globals_dict if globals_dict[name] is not None}

    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump({'run_id': run_id, 'results': results}, f, ensure_ascii=False)

if __name__ == '__main__':
    main()
